"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["32895"],{74897(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>o,contentTitle:()=>p,toc:()=>h,assets:()=>d});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-v2-update-cert","title":"Update certificate (v2, no passcode)","description":"Replaces a participant\'s public encryption certificate by participantId without passcode validation; the same schema is echoed back on success.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-v2-update-cert.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-v2-update-cert","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-v2-update-cert","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Update certificate (v2, no passcode)","sidebar_label":"Update certificate (v2, no passcode)","sidebar_class_name":"api-method api-method--post","description":"Replaces a participant\'s public encryption certificate by participantId without passcode validation; the same schema is echoed back on success.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"De-link ABHA policies","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-participant-delink-abha-policy"},"next":{"title":"Fetch certificate","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-fetch-certs"}}'),r=a(62540),n=a(43023),c=a(70862),s=JSON.parse('{"id":"registry_v2_update_cert","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/v2/update/cert","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Update certificate (v2, no passcode)","description":"Replaces a participant\'s public encryption certificate by participantId without passcode validation; the same schema is echoed back on success.\\n\\n### Business purpose\\n\\nEncryption keys are recommended to be rotated once a year, and a compromised key must be replaced immediately. The passcode-gated /v2/participant/update is the safer general route, but it needs a person with the registered phone and a 24-hour confirmation step. This endpoint exists for certificate-only updates without that validation, so an organisation can publish a new public certificate quickly. Only the certificate changes; the endpoint URL is untouched.\\n\\n### When to use\\n\\nUse it for scheduled annual rotation or emergency replacement of the certificate when passcode validation is not wanted. The production URL is https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/v2/update/cert. To change the callback URL as well, use /v2/participant/update instead. It is the last item of the certificates checklist alongside the v2 participant update. Synchronous JSON; no workflow or x-hcx-status codes.\\n\\n### Preconditions\\n\\n- Bearer token from /get/session in bearer_auth with the Bearer prefix; Accept and Content-Type: application/json.\\n- UpdateCertV2 body: participantId and certificate, both mandatory; the certificate must be Base64-encoded (the NHA steps produce a self-signed X.509 RSA certificate, then Base64-encode the whole PEM text).\\n- The matching new private key, in PKCS8 form, is already deployed on the callback host.\\n- Note the camelCase field participantId, unlike participant_code (v1) and participantcode (v2 update).\\n\\n### Postconditions\\n\\nHTTP 200 with the UpdateCertV2 schema echoed back (participantId and certificate). The registry\'s encryption certificate for that participant is replaced, so /fetch/certs returns the new one from the next call; counterparties may serve a cached copy for up to 24 hours. No transactionid is issued and no /update/validate step follows. No callback. 400, 404 and 500 use the ErrorResponse envelope.\\n\\n### Common mistakes\\n\\n- Sending the raw PEM rather than the Base64-encoded certificate, which the validation explicitly requires.\\n- Using participant_code, participantcode or encryptioncert; this schema is participantId and certificate.\\n- Publishing the new certificate before the new private key is live on the callback host, so inbound callbacks fail to decrypt (PAYR-1001 on the counterparty side, undecryptable payloads on yours).\\n- Discarding the old private key immediately, even though counterparties can hold the old certificate for 24 hours.\\n- Trying to change the endpoint URL here; only the certificate is accepted.\\n\\n### Best practices\\n\\n- Rotate in two phases: deploy the new PKCS8 private key, publish the certificate, and keep the old key for at least 24 hours.\\n- Generate a 2048-bit RSA key and a 365-day self-signed X.509 certificate so the validity matches the annual rotation recommendation.\\n- Verify with /participant/search or a /fetch/certs call against your own code that the new certificate is served.\\n- Restrict who can call this endpoint inside your organisation, since it replaces the key that protects all inbound health data without a passcode.\\n- Notify the ecosystem promptly if rotation is due to suspected compromise, as the protocol expects.\\n\\n### Related scenario\\n\\nA hospital\'s security audit finds its NHCX private key was copied to a shared drive. The team generates a new 2048-bit RSA key pair and 365-day self-signed certificate, deploys the PKCS8 private key to the callback host and Base64-encodes the certificate. With a Bearer token they call /v2/update/cert with participantId XXXXX7583@hcx and the certificate; the registry echoes the schema back. They keep the old key available for one day so payers still holding the cached certificate can be decrypted, then destroy it. The next /v1/preauth/on_submit from the payer, encrypted against the new certificate, decrypts cleanly.\\n\\n### Specification\\n\\nChapter [Your certificate](/docs/nhcx/v1/getting-started/your-certificate) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"participantId","type":"string","required":false,"description":"","encrypted":false},{"name":"certificate","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"participantId":"XXXX@hcx","certificate":"LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t..."},"responses":[{"status":"200","description":"HTTP 200 with the UpdateCertV2 schema echoed back (participantId and certificate).","example":{"participantId":"XXXX@hcx","certificate":"LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t..."}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","atom":"nhcx.endpoint.v2-update-cert","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/update/cert \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participantId\\": \\"XXXX@hcx\\",\\n  \\"certificate\\": \\"LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t...\\"\\n}\'"}');let o={title:"Update certificate (v2, no passcode)",sidebar_label:"Update certificate (v2, no passcode)",sidebar_class_name:"api-method api-method--post",description:"Replaces a participant's public encryption certificate by participantId without passcode validation; the same schema is echoed back on success.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},p,d={},h=[];function l(e){return(0,r.jsx)(c.A,{operation:s})}function u(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}}}]);